changeSet.sql:
ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update;
ALTER TABLE practice_revision DROP CONSTRAINT ck_practice_revision_fingerprint;
ALTER TABLE practice_revision ALTER COLUMN detection_fingerprint TYPE VARCHAR(96);
UPDATE practice_revision
SET detection_fingerprint = 'v1:' || detection_fingerprint
WHERE detection_fingerprint ~ '^[0-9a-f]{64}$';
ALTER TABLE practice_revision
    ADD CONSTRAINT ck_practice_revision_fingerprint
    CHECK (detection_fingerprint IS NULL OR detection_fingerprint ~ '^v[1-9][0-9]*:[0-9a-f]{64}$');
ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;

ALTER TABLE practice DROP CONSTRAINT ck_practice_curated_fingerprint;
ALTER TABLE practice ALTER COLUMN source_curated_fingerprint TYPE VARCHAR(96);
UPDATE practice
SET source_curated_fingerprint = 'v1:' || source_curated_fingerprint
WHERE source_curated_fingerprint ~ '^[0-9a-f]{64}$';
ALTER TABLE practice
    ADD CONSTRAINT ck_practice_curated_fingerprint
    CHECK (source_curated_fingerprint IS NULL OR source_curated_fingerprint ~ '^v[1-9][0-9]*:[0-9a-f]{64}$');

