ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update;

changeSet.sql:
ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
UPDATE config_audit_event SET entity_type = 'PRACTICE_USAGE' WHERE entity_type = 'PRACTICE_ACTIVE';
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
    CHECK (entity_type IN (
        'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
        'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
        'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_USAGE',
        'PRACTICE_DEFINITION', 'PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA',
        'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
        'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
        'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
    ));

rollback.sql:
ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
UPDATE config_audit_event SET entity_type = 'PRACTICE_ACTIVE' WHERE entity_type = 'PRACTICE_USAGE';
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
    CHECK (entity_type IN (
        'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
        'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
        'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE',
        'PRACTICE_DEFINITION', 'PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA',
        'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
        'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
        'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
    ));

DO $rollback$ BEGIN IF to_regclass('workspace_agent_binding') IS NOT NULL THEN UPDATE workspace_agent_binding SET purpose = 'PRACTICE_DETECTION' WHERE purpose = 'PRACTICE_REVIEW'; END IF;
IF EXISTS ( SELECT 1 FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'agent_job' AND column_name = 'purpose' ) THEN UPDATE agent_job SET purpose = 'PRACTICE_DETECTION' WHERE purpose = 'PRACTICE_REVIEW'; END IF;
IF to_regclass('config_audit_event') IS NOT NULL THEN UPDATE config_audit_event SET entity_id = CASE WHEN entity_id = 'PRACTICE_REVIEW' THEN 'PRACTICE_DETECTION' ELSE entity_id END, old_value = CASE WHEN old_value->>'purpose' = 'PRACTICE_REVIEW' THEN jsonb_set(old_value, '{purpose}', '"PRACTICE_DETECTION"') ELSE old_value END, new_value = CASE WHEN new_value->>'purpose' = 'PRACTICE_REVIEW' THEN jsonb_set(new_value, '{purpose}', '"PRACTICE_DETECTION"') ELSE new_value END WHERE entity_id = 'PRACTICE_REVIEW' OR old_value->>'purpose' = 'PRACTICE_REVIEW' OR new_value->>'purpose' = 'PRACTICE_REVIEW'; END IF; END $rollback$;
